@@ -431,6 +431,23 @@ export const extendTransform = (expression: string): { code: string } | undefine
 			},
 		});

+		// Mixing `??` with `&&`/`||` without parentheses is a syntax error, and recast
+		// can drop the original parentheses when it reprints a modified parent node.
+		visit(ast, {
+			visitLogicalExpression(path) {
+				this.traverse(path);
+
+				if (path.node.operator === '??') {
+					for (const side of [path.node.left, path.node.right]) {
+						if (side.type === 'LogicalExpression' && side.operator !== '??') {
+							const node = side as { extra?: { parenthesized?: boolean } };
+							node.extra = { ...node.extra, parenthesized: true };
+						}
+					}
+				}
+			},
+		});
+
 		return print(ast);
 	} catch (e) {
 		return;
diff --git a/packages/workflow/test/ExpressionExtensions/expression-extension.test.ts b/packages/workflow/test/ExpressionExtensions/expression-extension.test.ts
