--- a/packages/workflow/test/ExpressionExtensions/expression-extension.test.ts
+++ b/packages/workflow/test/ExpressionExtensions/expression-extension.test.ts
@@ -136,6 +136,15 @@ describe('Expression Parser', () => {
 	});

 	describe('Test newer ES syntax', () => {
+		test('Keeps parentheses around && and || operands of ??', () => {
+			expect(extendTransform('(a && b) ?? c')?.code).toBe('(a && b) ?? c');
+			expect(extendTransform('a ?? (b || c)')?.code).toBe('a ?? (b || c)');
+			expect(extendTransform('(a || b) ?? c.first()')?.code).toBe(
+				'(a || b) ?? extend(c, "first", [])',
+			);
+			expect(extendTransform('x?.y ?? (a||b)')?.code).toMatch(/\?\? \(a \|\| b\)$/);
+		});
+
 		test('Optional chaining transforms', () => {
 			expect(extendTransform('$json.something?.test.funcCall()')?.code).toBe(
 				'window.chainCancelToken1 = ((window.chainValue1 = $json.something) ?? undefined) === undefined, window.chainCancelToken1 === true ? undefined : window.chainValue1.test.funcCall();',
